import numpy as np

def make_obs(agent=(5,5), reward=None, moving=None, obstacle=None):
    x = np.zeros((10,10,5), dtype=float)
    # wall border in obstacle channel
    x[0,:,3] = 1
    x[9,:,3] = 1
    x[:,0,3] = 1
    x[:,9,3] = 1
    if agent is not None:
        x[agent[0], agent[1], 0] = 1
    if reward is not None:
        x[reward[0], reward[1], 2] = 1
    if moving is not None:
        x[moving[0], moving[1], 1] = 1
    if obstacle is not None:
        x[obstacle[0], obstacle[1], 3] = 1
    # previous frame = current agent/moving-object cells
    x[:,:,4] = np.maximum(x[:,:,0], x[:,:,1])
    return x.flatten()

conditions = []
conditions.append(("base", make_obs()))

neighbors = [
    (-1, 0, "U"), (1, 0, "D"), (0, -1, "L"), (0, 1, "R"),
    (-1, -1, "UL"), (-1, 1, "UR"), (1, -1, "DL"), (1, 1, "DR")
]

for dr, dc, name in neighbors:
    conditions.append((f"reward_{name}", make_obs(reward=(5+dr, 5+dc))))

for dr, dc, name in neighbors:
    conditions.append((f"moving_{name}", make_obs(moving=(5+dr, 5+dc))))

for dr, dc, name in neighbors:
    conditions.append((f"obstacle_{name}", make_obs(obstacle=(5+dr, 5+dc))))

X = np.array([c[1] for c in conditions])
logits = forward(X)

for (name, _), lg in zip(conditions, logits):
    print(f"{name:12s} argmax={np.argmax(lg)} logits={np.round(lg, 2)}")

import numpy as np

def make_obs(agent, movings=[], rewards=[], obstacles=[], prev=None):
    grid = np.zeros((10,10,5), dtype=float)
    # walls
    for r in range(10):
        for c in range(10):
            if r==0 or r==9 or c==0 or c==9:
                grid[r,c,3] = 1.0
    if agent is not None:
        grid[agent[0], agent[1], 0] = 1.0
    for pos in movings:
        grid[pos[0], pos[1], 1] = 1.0
    for pos in rewards:
        grid[pos[0], pos[1], 2] = 1.0
    for pos in obstacles:
        grid[pos[0], pos[1], 3] = 1.0
    if prev is None:
        prev_agent = agent
        prev_movings = movings
    else:
        prev_agent, prev_movings = prev
    if prev_agent is not None:
        grid[prev_agent[0], prev_agent[1], 4] = 1.0
    for pos in prev_movings:
        grid[pos[0], pos[1], 4] = 1.0
    return grid.flatten()

scenarios = []
scenarios.append(("base_center", make_obs((4,4))))
scenarios.append(("box_right", make_obs((4,4), movings=[(4,5)])))
scenarios.append(("goal_right", make_obs((4,4), rewards=[(4,5)])))
scenarios.append(("push_right", make_obs((4,4), movings=[(4,5)], rewards=[(4,6)])))
scenarios.append(("push_up", make_obs((4,4), movings=[(3,4)], rewards=[(2,4)])))
scenarios.append(("push_down", make_obs((4,4), movings=[(5,4)], rewards=[(6,4)])))
scenarios.append(("push_left", make_obs((4,4), movings=[(4,3)], rewards=[(4,2)])))
scenarios.append(("box_on_goal", make_obs((4,4), movings=[(4,5)], rewards=[(4,5)])))
scenarios.append(("frogger_bottom", make_obs((8,4), rewards=[(1,4)])))
scenarios.append(("frogger_car", make_obs((8,4), movings=[(5,4)], rewards=[(1,4)])))

batch = np.array([obs for name, obs in scenarios])
logits = forward(batch)
print("action order: 0 noop, 1 up, 2 down, 3 left, 4 right")
print(f"{'scenario':<15} {'noop':>6} {'up':>6} {'down':>6} {'left':>6} {'right':>6}  argmax")
for (name, _), lg in zip(scenarios, logits):
    am = int(np.argmax(lg))
    print(f"{name:<15} {lg[0]:6.2f} {lg[1]:6.2f} {lg[2]:6.2f} {lg[3]:6.2f} {lg[4]:6.2f}  {am}")
